```c
/* C: a growable int array with an explicit growth policy. */
typedef struct { int *data; size_t len, cap; } IntVec;

int push(IntVec *v, int x) {
    if (v->len == v->cap) {                        /* full: double the capacity. */
        size_t cap = v->cap ? 2 * v->cap : 4;
        int *p = realloc(v->data, cap * sizeof *p);
        if (!p) return -1;                        /* allocation failed. */
        v->data = p; v->cap = cap;                /* old pointers into data are now invalid. */
    }
    v->data[v->len++] = x;
    return 0;
}
```

